(()=>{'use strict';const B=ExamBank,C=ExamCore,key='science-studio-exam-v1',root=document.querySelector('#examPractice');let selected='electricity',level='all',notice='',data;
try{const saved=localStorage.getItem(key);data=C.clean(B,saved?JSON.parse(saved):null)}catch(e){data=C.clean(B,null);notice='Saved exam progress could not be read. You can practise, but previous progress has not been restored.';}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),Q=s=>root.querySelector(s);
function save(){try{localStorage.setItem(key,JSON.stringify(data));notice='Progress and drafts saved in this browser.'}catch(e){notice='Browser storage is unavailable or full. Changes are kept for this session only; export a copy before leaving.'}if(Q('#examSave'))Q('#examSave').textContent=notice;}
const stimuli={
motionGraph:`<figure class="examfigure"><svg viewBox="0 0 500 240" role="img" aria-label="Velocity rises linearly from 0 metres per second at 0 seconds to 6 at 4 seconds, then stays at 6 until 6 seconds."><path d="M60 25V190H455" fill="none" stroke="#173b3b" stroke-width="2"/><path d="M60 190L300 55H420" fill="none" stroke="#238780" stroke-width="4"/><path d="M60 55H300V190M420 55V190" fill="none" stroke="#a8b6ae" stroke-dasharray="5 4"/><g fill="#173b3b" font-size="16" text-anchor="middle"><text x="38" y="195">0</text><text x="38" y="60">6</text><text x="60" y="213">0</text><text x="300" y="213">4</text><text x="420" y="213">6</text><text x="260" y="238">Time (s)</text><text x="180" y="22">Velocity (m/s)</text></g></svg><figcaption>Original graph. Velocity is positive throughout.</figcaption></figure>`,
tree:`<figure class="examfigure"><svg viewBox="0 0 500 220" role="img" aria-label="Rooted tree: A and B share the most recent node. That pair shares an older node with C. D branches from the oldest node shown."><path d="M40 120H90M90 60V180H420M90 60H190M190 40V120H420M190 40H300M300 25V75M300 25H420M300 75H420" fill="none" stroke="#238780" stroke-width="3"/><g fill="#173b3b" font-size="18"><text x="435" y="31">A</text><text x="435" y="81">B</text><text x="435" y="126">C</text><text x="435" y="186">D</text><text x="35" y="211" font-size="12">Root → branching history; branch lengths are not time-scaled</text></g></svg></figure>`,
rateTable:`<div class="examtable"><table><caption>Original gas-production data</caption><thead><tr><th scope="col">Time (s)</th><th scope="col">Gas volume (cm³)</th></tr></thead><tbody><tr><td>0</td><td>0</td></tr><tr><td>10</td><td>20</td></tr><tr><td>20</td><td>32</td></tr><tr><td>30</td><td>38</td></tr><tr><td>40</td><td>40</td></tr><tr><td>50</td><td>40</td></tr></tbody></table></div>`
};
root.innerHTML=`<div class="sectionhead"><div><div class="eyebrow">04 / EXAM PRACTICE</div><h2>Show what you understand.</h2></div><span class="pill">66 QUESTIONS · CORE + EXTENSION</span></div><p>Choose a topic, check your reasoning, then write an exam response. Original and adapted practice informed by the supplied past papers; these are practice marking guides, not official exam keys.</p><div id="examDashboard" class="examdashboard"></div><p id="examSave" class="small" role="status">${esc(notice||'Progress and drafts stay in this browser. They do not sync between devices.')}</p><div id="examChoices" class="examchoices" aria-label="Choose an exam topic"></div><div class="examtoolbar"><label for="examLevel">Show questions <select id="examLevel"><option value="all">Core + extension</option><option value="core">Core only</option><option value="extension">Extension only</option></select></label><button id="examExport">Export progress (JSON)</button><button id="examClear">Reset exam progress</button><span id="examClearConfirm" hidden>Clear all exam scores and drafts? <button id="examClearYes">Confirm reset</button> <button id="examClearNo">Cancel</button></span></div><div id="examTopic"></div>`;
function totals(){let checked=0,correct=0,written=0,complete=0;for(const t of B.topics){let s=C.summary(t,data.topics[t.id]);checked+=s.firstCount;correct+=s.firstCorrect;written+=s.written;complete+=Number(s.checked===s.total&&s.written===s.writtenTotal)}return {checked,correct,written,complete};}
function dashboard(){const t=totals();Q('#examDashboard').innerHTML=`<div><b>${t.complete}/11</b><span>topic sets complete</span></div><div><b>${t.checked}/44</b><span>auto questions tried</span></div><div><b>${t.correct}/${t.checked}</b><span>correct on first check</span></div><div><b>${t.written}/22</b><span>written answers self-assessed</span></div>`;Q('#examChoices').innerHTML=B.topics.map(t=>{let s=C.summary(t,data.topics[t.id]);return `<button data-exam-topic="${t.id}" aria-pressed="${t.id===selected}"><b>${esc(t.title)}</b><span>${s.checked}/4 checked · ${s.written}/2 written</span></button>`}).join('');Q('#examChoices').querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=b.dataset.examTopic;render()});}
function render(){dashboard();const topic=B.topics.find(t=>t.id===selected),s=data.topics[selected],stats=C.summary(topic,s);Q('#examTopic').innerHTML=`<div class="examtopichead"><div><h3>${esc(topic.title)}</h3><p id="examScore">Run ${s.run}: ${stats.correct} correct from ${stats.checked}/4 checked. Best complete run: ${s.best===null?'not yet completed':s.best+'/4'}.</p><p class="small">A topic set is complete after all four auto questions are checked and both written answers are self-assessed. Filtering does not change these totals.</p></div><button id="examRetry">Retry this topic’s auto quiz</button></div><details class="examsource"><summary>Question sources and scope</summary><p>${esc(topic.source)}</p><p>Core/extension labels describe practice difficulty; they are not official school grade boundaries.</p></details><div class="examquestions">${topic.questions.filter(q=>level==='all'||q.level===level).map(q=>question(q,s.questions[q.id])).join('')}</div>`;wire(topic);}
function question(q,r){const feedback=r.checked?`<div class="examfeedback ${C.grade(q,r.answer)?'right':'wrong'}" role="status" tabindex="-1"><b>${C.grade(q,r.answer)?'Correct · 1/1':'Not yet · 0/1'}</b><p>${esc(q.explain)}</p>${C.grade(q,r.answer)?'':`<p><b>Answer:</b> ${esc(q.type==='mc'?q.options[q.correct]:q.answer+' '+q.unit)}</p>`}</div>`:'';
if(q.type==='written')return `<article class="examquestion" data-q="${q.id}"><div class="examqmeta">${q.level} · written response · ${q.marks} marks</div><h4>${esc(q.prompt)}</h4>${stimuli[q.stimulus]||''}<label for="draft-${q.id}" class="small">Your response (saved as you type; up to 6,000 characters)</label><textarea id="draft-${q.id}" rows="5" maxlength="6000" data-draft="${q.id}">${esc(r.draft)}</textarea><details class="examguide"><summary>Reveal model answer & marking guide</summary><p><b>Model answer</b><br>${esc(q.model)}</p><p>Tick only the points demonstrated in your own response. Each point is worth one mark. Alternative scientifically correct wording earns credit.</p>${q.rubric.map((point,i)=>`<label class="examcriterion"><input type="checkbox" data-rubric="${q.id}" data-index="${i}" ${r.rubric[i]?'checked':''}> <span>${esc(point)}</span></label>`).join('')}<button data-assess="${q.id}" ${!r.draft.trim()?'disabled':''}>Save my self-assessment</button></details><p class="small" id="written-${q.id}" role="status">${r.assessed?`Self-assessed ${r.rubric.filter(Boolean).length}/${q.marks} marks · not automatically graded.`:'Not yet self-assessed. Write a response, then use the marking guide.'}</p></article>`;
return `<article class="examquestion" data-q="${q.id}"><div class="examqmeta">${q.level} · ${q.type==='number'?'calculation':'multiple choice'} · 1 mark</div><fieldset ${r.checked?'disabled':''}><legend>${esc(q.prompt)}</legend>${stimuli[q.stimulus]||''}${q.type==='mc'?q.options.map((x,i)=>`<label class="examoption"><input type="radio" name="${q.id}" value="${i}" data-answer="${q.id}" ${r.answer===i?'checked':''}><span><b>${String.fromCharCode(65+i)}.</b> ${esc(x)}</span></label>`).join(''):`<label for="answer-${q.id}" class="examnumber">Answer in ${esc(q.unit)}<input id="answer-${q.id}" inputmode="decimal" type="text" maxlength="30" data-answer="${q.id}" value="${esc(r.answer??'')}" placeholder="Enter a number only"></label>`}</fieldset><button data-check="${q.id}" ${r.checked||!C.validAnswer(q,r.answer)?'disabled':''}>${r.checked?'Answer checked':'Check answer'}</button><span class="small examinputhint" id="hint-${q.id}">${q.type==='number'?'Enter a number only; the unit is shown above.':''}</span>${feedback}</article>`;}
function updateScore(topic){const s=data.topics[topic.id],x=C.summary(topic,s);Q('#examScore').textContent=`Run ${s.run}: ${x.correct} correct from ${x.checked}/4 checked. Best complete run: ${s.best===null?'not yet completed':s.best+'/4'}.`;dashboard();}
function wire(topic){const s=data.topics[topic.id];Q('#examRetry').onclick=()=>{C.retry(topic,s);save();render()};Q('#examTopic').querySelectorAll('[data-answer]').forEach(e=>e.oninput=()=>{const q=topic.questions.find(q=>q.id===e.dataset.answer),r=s.questions[q.id];if(r.checked)return;r.answer=q.type==='mc'?Number(e.value):e.value;Q(`[data-check="${q.id}"]`).disabled=!C.validAnswer(q,r.answer);save()});Q('#examTopic').querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>{if(!C.check(topic,s,b.dataset.check))return;save();const q=topic.questions.find(q=>q.id===b.dataset.check),article=Q(`[data-q="${q.id}"]`);article.outerHTML=question(q,s.questions[q.id]);Q(`[data-q="${q.id}"] .examfeedback`).focus();wireQuestionEvents(topic);updateScore(topic);});wireWritten(topic);}
function wireQuestionEvents(topic){/* Rebind changed controls without replacing draft fields or open marking guides. */const s=data.topics[topic.id];Q('#examTopic').querySelectorAll('[data-check]').forEach(b=>{if(b.disabled)return;b.onclick=()=>{if(!C.check(topic,s,b.dataset.check))return;save();const q=topic.questions.find(q=>q.id===b.dataset.check);Q(`[data-q="${q.id}"]`).outerHTML=question(q,s.questions[q.id]);Q(`[data-q="${q.id}"] .examfeedback`).focus();wireQuestionEvents(topic);updateScore(topic);}});}
function wireWritten(topic){const s=data.topics[topic.id];Q('#examTopic').querySelectorAll('[data-draft]').forEach(e=>e.oninput=()=>{const id=e.dataset.draft,r=s.questions[id];r.draft=e.value;r.assessed=false;Q(`[data-assess="${id}"]`).disabled=!r.draft.trim();Q(`#written-${id}`).textContent='Draft changed. Review the marking guide and save a new self-assessment.';save();updateScore(topic)});Q('#examTopic').querySelectorAll('[data-rubric]').forEach(e=>e.onchange=()=>{const id=e.dataset.rubric,r=s.questions[id];r.rubric[Number(e.dataset.index)]=e.checked;r.assessed=false;Q(`#written-${id}`).textContent='Marking points changed. Save your self-assessment to update progress.';save();updateScore(topic)});Q('#examTopic').querySelectorAll('[data-assess]').forEach(b=>b.onclick=()=>{const id=b.dataset.assess,r=s.questions[id],q=topic.questions.find(q=>q.id===id);if(!r.draft.trim())return;r.assessed=true;Q(`#written-${id}`).textContent=`Self-assessed ${r.rubric.filter(Boolean).length}/${q.marks} marks · not automatically graded.`;save();updateScore(topic)});}
Q('#examClear').onclick=()=>Q('#examClearConfirm').hidden=false;Q('#examClearNo').onclick=()=>Q('#examClearConfirm').hidden=true;Q('#examClearYes').onclick=()=>{data=C.clean(B,null);Q('#examClearConfirm').hidden=true;save();render();};Q('#examLevel').onchange=e=>{level=e.target.value;render()};Q('#examExport').onclick=()=>{const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),...data},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='science-studio-exam-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
window.addEventListener('science-exam-topic',e=>{if(B.topics.some(t=>t.id===e.detail)){selected=e.detail;level='all';Q('#examLevel').value='all';render();root.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}});render();
})();
